-- SCRIPT DE DATOS INICIALES - CONTABILIDAD
-- RUTA: c:\Proyectos\Contabilidad\SQL\Data\Inicial.sql
-- IDEMPOTENTE: Puede ejecutarse múltiples veces sin errores

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 1. Rol Admin
VALUES ('ADMIN', 'Admin', 'Administrador del sistema')
ON CONFLICT (code) DO NOTHING;

-- 2. Usuario inicial (clave encriptada con bcrypt via pgcrypto)
VALUES (
    'BOG',
    'rubiel1985@msn.com',
    crypt('111985', gen_salt('bf')),
    NULL,
    '2030-01-01 00:00:00',
    (SELECT id FROM public."Roles" WHERE code = 'ADMIN' LIMIT 1)
)
ON CONFLICT (name) DO UPDATE
    SET "passwordHash" = CASE
        WHEN public."User"."passwordHash" = '111985' THEN crypt('111985', gen_salt('bf'))
        ELSE public."User"."passwordHash"
    END;

-- 3. Tercero, Clientes, Proveedores, Vendedores
VALUES ('73009263', 'Rubiel')
ON CONFLICT (code) DO NOTHING;

VALUES ('73009263', 'Rubiel', 'rubiel1985@msn.com', (SELECT id FROM public."Third" WHERE code = '73009263' LIMIT 1))
ON CONFLICT (code) DO NOTHING;

VALUES ('73009263', 'Rubiel', 'rubiel1985@msn.com', (SELECT id FROM public."Third" WHERE code = '73009263' LIMIT 1))
ON CONFLICT (code) DO NOTHING;

VALUES ('73009263', 'Rubiel', 'rubiel1985@msn.com')
ON CONFLICT (code) DO NOTHING;


-- 4. Parámetros del sistema
ON CONFLICT (code) DO UPDATE
    SET "order"     = EXCLUDED."order",
        name        = EXCLUDED.name,
        value       = EXCLUDED.value,
        description = EXCLUDED.description;

-- 4b. Tipo de documento y Fuente por defecto para Nota Contable
VALUES ('NC', 'Nota Contable', 'Documento de ajuste y nota contable', true)
ON CONFLICT (code) DO NOTHING;

VALUES (
    'NC',
    'Nota Contable',
    'Fuente para notas contables manuales',
    'nota_contable',
    true,
    (SELECT id FROM public."DocumentType" WHERE code = 'NC' LIMIT 1)
)
ON CONFLICT (code) DO NOTHING;


